def patched_launcher(name, repo, artifacts, base):
    source = FROZEN_SOURCES[name]
    source = source.replace(HISTORICAL_XATTN, artifacts.as_posix())
    source = source.replace(HISTORICAL_BASE, base)
    source = re.sub(r'^REPO_ROOT=.*$', 'REPO_ROOT=' + shlex.quote(repo.as_posix()), source, flags=re.M)
    # Repair a removed historical verifier directory in archived launchers.
    source = source.replace('ft_scripts/conv_ruler/verify_conv_kernel.py', 'ft_scripts/sparse_ruler/verify_conv_kernel.py')
    return source


def plans(args):
    repo = args.repo.resolve()
    out = args.output_dir.resolve()
    artifacts = out / 'weights'
    nolima = args.nolima_root or args.base + '/Repos/fuyicheng_workshop/dllm/data/NoLiMa'
    model_root = args.model_root or args.base + '/Resources/models/LLMs'
    w = artifacts / 'conv_weights'
    q = artifacts / 'qwen_weights'
    q_boot = q / 'initial' / 'qwen_initial.pt'
    llama_base = w / 'conv_kernel_7x7_ruler_mix_sparse_guarded_long_t07_24k32k_bf16.pt'
    llama_long = w / 'conv_kernel_7x7_ruler_mix_sparse_guarded_long_t07_96k128k_refine_from18000_bf16.pt'
    llama_polish = w / 'conv_kernel_7x7_ruler_mix_sparse_guarded_long_t07_96k128k_continue_from4000_v1_bf16.pt'
    llama_final_dir = artifacts / 'llama_final'
    q_extend_dir = q / 'conv_qwen3_t065_64k128k_balanced_v3'
    q_stage3 = q_extend_dir / 'stage3_extend_96k128k_t065_s8_yarn4_bf16_ema_step9250.pt'
    q_final = q / 'conv_qwen3_t065_longbench_stage4_v2' / 'conv_kernel_7x7_qwen3_t065_longbench_replay_native_8k64k_s8_bf16.pt'
    initial_data = args.qwen_initial_data or nolima + '/synth_train/qwen3_8b_ruler_mix_sparse_t065_48k64k_multikey_qa2_16000.jsonl'
    def stage(name, env, expected, description, **extra):
        source = patched_launcher(name, repo, artifacts, args.base) if name in FROZEN_SOURCES else ''
        # Every training run uses independent weight/log destinations.
        env = dict(env, NOLIMA_ROOT=nolima, LOG_DIR=str(out / 'logs' / name), AUTO_RESUME='1')
        return dict(name=name, env=env, expected=str(expected), description=description, source=source, **extra)
    llama = [
        stage('llama_initial', {'INIT_PATH':'identity', 'TRAIN_STEPS':'18000', 'OUT_PATH':str(llama_base)}, llama_base.with_name(llama_base.stem+'_step18000.pt'), 'Identity -> 24K--32K, 18000 steps; select raw step18000'),
        stage('llama_long', {'INIT_PATH':str(llama_base.with_name(llama_base.stem+'_step18000.pt')), 'TRAIN_STEPS':'5000', 'OUT_PATH':str(llama_long)}, llama_long.with_name(llama_long.stem+'_ema_step4000.pt'), '96K--128K, configured 5000 steps; select EMA step4000'),
        stage('llama_polish', {'INIT_PATH':str(llama_long.with_name(llama_long.stem+'_ema_step4000.pt')), 'TRAIN_STEPS':'6000', 'OUT_PATH':str(llama_polish)}, llama_polish.with_name(llama_polish.stem+'_ema.pt'), '96K--128K low-rate stage, 6000 steps'),
        stage('llama_final', {'INIT_PATH':str(llama_polish.with_name(llama_polish.stem+'_ema.pt')), 'TRAIN_STEPS':'2000', 'RUN_DIR':str(llama_final_dir), 'TOPP':'0.92'}, llama_final_dir/'conv_kernel_7x7_llama4000_ruler10_replay_ema.pt', '112K--128K with 8K--64K replay, 2000 steps'),
    ]
    initial_params = dict(QWEN_INITIAL_PARAMS, model=model_root+'/Qwen3-8B', data=str(initial_data), out=str(q_boot))
    initial_command = ['python', 'ft_scripts/sparse_ruler_qwen/train_conv_kernel_guarded_long.py']
    for key, value in initial_params.items():
        initial_command.extend(['--'+key, value])
    qwen = [
        stage('qwen_initial', {}, q_boot.with_name(q_boot.stem+'_ema_step16000.pt'), 'Identity -> 48K--64K, 16000 steps, stride16 (logged)', command=initial_command, original_training_data=str(initial_data)),
        stage('qwen_extend', {'BASE_INIT':str(q_boot.with_name(q_boot.stem+'_ema_step16000.pt')), 'RUN_NAME':'conv_qwen3_t065_64k128k_balanced_v3', 'STOP_AFTER_STAGE3':'1', 'STAGE1_STEPS':'6000', 'STAGE2_STEPS':'8000', 'STAGE3_STEPS':'9250'}, q_stage3, '48K--72K (6000) -> 64K--96K (8000) -> 96K--128K (9250), stride8 / YaRN4'),
        stage('qwen_final', {'STAGE3_INIT':str(q_stage3), 'TRAIN_STEPS':'5000', 'OUT_PATH':str(q_final), 'RUN_NAME':'conv_qwen3_t065_longbench_stage4_v2'}, q_final.with_name(q_final.stem+'_ema_step5000.pt'), 'Native-RoPE 8K--64K calibration, 5000 steps'),
    ]
    # Initial model paths in historical scripts are frozen but remapped above.
    # A user-supplied model/data root takes priority even in hardcoded launchers.
    for s in llama+qwen:
        s['source'] = re.sub(r'^MODEL_PATH=.*$', 'MODEL_PATH='+shlex.quote(model_root + ('/Qwen3-8B' if s['name'].startswith('qwen') else '/Llama-3.1-8B-Instruct')), s['source'], flags=re.M)
        s['source'] = re.sub(r'^NOLIMA_ROOT=.*$', 'NOLIMA_ROOT='+shlex.quote(nolima), s['source'], flags=re.M)
    return llama if args.model=='llama' else qwen if args.model=='qwen' else llama+qwen


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--model', choices=['llama','qwen','all'], default='all')
    p.add_argument('--repo', type=Path, default=Path(__file__).resolve().parents[1])
    p.add_argument('--output-dir', type=Path, default=Path(__file__).resolve().parents[1]/'output/final_weight_multistage_backup')
    p.add_argument('--base', default=HISTORICAL_BASE)
    p.add_argument('--model-root')
    p.add_argument('--nolima-root')
    p.add_argument('--qwen-initial-data', help='Original 16000-example Qwen training JSONL, not benchmark evaluation data')
    p.add_argument('--execute', action='store_true', help='Start GPU training; without this flag only print the archived plan')
    p.add_argument('--dry-run', action='store_true', help='Explicitly print the plan without writing files or training')
    args = p.parse_args()
    stages = plans(args)
    for s in stages:
        print(s['name'] + ': ' + s['description'])
        print('  selected output: ' + s['expected'])
    print('Archive scope: logged Qwen initialization plus saved launcher recipes; later historical overrides are not fully logged.')
    if args.dry_run or not args.execute:
        return
    if os.name=='nt':
        p.error('Training requires a Linux CUDA host and bash; Windows supports plan inspection only.')
    repo=args.repo.resolve()
    out=args.output_dir.resolve()
    # Validate every dependency before any training starts.
    for relative in ['ft_scripts/sparse_ruler/train_conv_kernel_guarded_long.py', 'ft_scripts/sparse_ruler/build_ruler_mix_sft.py', 'ft_scripts/sparse_ruler/verify_conv_kernel.py', 'ft_scripts/sparse_ruler_qwen/train_conv_kernel_guarded_long.py']:
        if not (repo/relative).is_file():
            p.error('Missing repository dependency: '+relative)
    for s in stages:
        if s.get('original_training_data') and not Path(s['expected']).is_file():
            data=Path(s['original_training_data'])
            if not data.is_file():
                p.error('Missing original Qwen training JSONL; use --qwen-initial-data. Its historical generation settings are not reconstructed.')
            with data.open(encoding='utf-8') as f:
                if sum(1 for line in f if line.strip()) != 16000:
                    p.error('Qwen initialization requires the recorded 16000-example training JSONL.')
    (out/'launchers').mkdir(parents=True, exist_ok=True)
    (out/'logs').mkdir(exist_ok=True)
    manifest={'archive_version':'2026-10-09', 'source_sha256':{n:hashlib.sha256(v.encode()).hexdigest() for n,v in FROZEN_SOURCES.items()}, 'source_paths':SOURCE_PATHS, 'stages':[{k:v for k,v in s.items() if k!='source'} for s in stages]}
    (out/'training_plan.json').write_text(json.dumps(manifest, indent=2)+'\n', encoding='utf-8')
    for s in stages:
        if Path(s['expected']).is_file():
            print('[skip] selected output exists: '+s['expected'])
            continue
        env=dict(os.environ, **s['env'])
        env['PYTHONPATH']=str(repo)+os.pathsep+env.get('PYTHONPATH','')
        env.setdefault('TOKENIZERS_PARALLELISM','false')
        env.setdefault('PYTORCH_CUDA_ALLOC_CONF','expandable_segments:True,max_split_size_mb:128')
        env['CONV_TOPP_SELECTOR']='positive'
        if 'command' in s:
            Path(s['command'][s['command'].index('--out')+1]).parent.mkdir(parents=True, exist_ok=True)
            command=list(s['command'])
            command[0]=sys.executable
            state=Path(command[command.index('--out')+1]).with_name('qwen_initial_train_state.pt')
            if state.is_file():
                command.extend(['--resume_state',str(state)])
        else:
            launcher=out/'launchers'/(s['name']+'.sh')
            launcher.write_text(s['source'],encoding='utf-8',newline='\n')
            command=['bash',str(launcher)]
            if s['env'].get('OUT_PATH'):
                state=Path(s['env']['OUT_PATH']).with_name(Path(s['env']['OUT_PATH']).stem+'_train_state.pt')
            elif s['name']=='llama_final':
                state=Path(s['env']['RUN_DIR'])/'conv_kernel_7x7_llama4000_ruler10_replay_train_state.pt'
            else:
                state=None
            if state and state.is_file():
                env['RESUME_STATE']=str(state)
        with (out/'logs'/(s['name']+'.log')).open('a',encoding='utf-8') as log:
            print('[run] '+s['name'],flush=True)
            subprocess.run(command,cwd=repo,env=env,stdout=log,stderr=subprocess.STDOUT,check=True)
        if not Path(s['expected']).is_file():
            raise RuntimeError('Stage did not produce the selected output: '+s['expected'])
    print('Selected final weight paths are recorded in '+str(out/'training_plan.json'))


if __name__=='__main__':
    main()
